// сумма чисел меньше n, кратных 3 или 5
fun sumMultiples(n: Int): Long {
    var sum = 0L
    for (i in 1 until n) {
        if (i % 3 == 0 || i % 5 == 0) {
            sum += i
        }
    }
    return sum
}

fun main() {
    println(sumMultiples(10))
}

