import kotlin.math.abs

// сумма цифр: 1990 -> 1 + 9 + 9 + 0 = 19
fun digitSum(n: Long): Int {
    val m = abs(n)
    if (m < 10) return m.toInt()
    return (m % 10).toInt() + digitSum(m / 10)
}

fun main() {
    println(digitSum(1990))
}

content.tests_code:
