    Check.eq("0", 0) { digitSum(0) }
    Check.eq("7", 7) { digitSum(7) }
    Check.eq("1990", 19) { digitSum(1990) }
    Check.eq("123456789", 45) { digitSum(123456789) }
    Check.eq("возврат -1990", 19) { digitSum(-1990) }
    Check.eq("длинный 9999999999", 90) { digitSum(9_999_999_999) }
}

