fun parsePort(s: String): Int {
    try {
        println("разбираю $s")
        return s.toInt()
    } catch (e: NumberFormatException) {
        println("не число: $s")
        return -1
    } finally {
        println("готово")
    }
}

fun main() {
    println(parsePort("8080"))
    println(parsePort("80a"))
    println("80a".toIntOrNull())
    val port = try { "x".toInt() } catch (e: NumberFormatException) { 8080 }
    println(port)
    println(runCatching { "7".toInt() * 2 }.getOrDefault(0))
    println(runCatching { "семь".toInt() }.getOrDefault(0))
}

fun port(s: String): Int {
    val n = s.[[1]]() [[2]] throw IllegalArgumentException("порт «$s» — не число")
    [[3]](n in 1..65535) { "порт $n вне диапазона" }
    return n
}

fun main() {
    println(port("8080"))
}

