content.correct_answer:
class StockException(val want: Int, val have: Int) :
    RuntimeException("не хватает товара: нужно $want, есть $have")

// резерв товара: остаток или исключение
fun reserve(have: Int, want: Int): Int {
    require(want > 0) { "количество должно быть больше нуля" }
    if (want > have) throw StockException(want, have)
    return have - want
}

fun main() {
    println(reserve(10, 3))
}

content.tests_code:
// ловим StockException, чтобы тест увидел его данные
fun call(have: Int, want: Int): String =
    try {
        reserve(have, want).toString()
    } catch (e: StockException) {
        "StockException(want=${e.want}, have=${e.have})"
    }

fun tests() {
    Check.eq("резерв 3 из 10", "7") { call(10, 3) }
    Check.eq("забрать всё", "0") { call(4, 4) }
    Check.eq("не хватает: нужно 5, есть 2", "StockException(want=5, have=2)") { call(2, 5) }
    Check.throws<IllegalArgumentException>("количество 0") { call(10, 0) }
}
